use xiom.io;

use xiom.string;
fn main() -> Int {
  let tasks: Vec[Str] = Vec[Str].new();
  tasks.push("Walk dog");
  tasks.push("Read book");
  tasks.push("Write code");

  io.println("Todo List:");
  let i: Int = 0;
  while i < tasks.len() {
    match tasks.get(i) {
      Some(t) -> io.println(string.int_to_str(i + 1) + ". " + t);
      None -> {}
    }
    i = i + 1;
  }

  tasks.push("Exercise");
  io.println("\nAdded 'Exercise':");
  let j: Int = 0;
  while j < tasks.len() {
    match tasks.get(j) {
      Some(t) -> io.println(string.int_to_str(j + 1) + ". " + t);
      None -> {}
    }
    j = j + 1;
  }

  match tasks.pop() {
    Some(done) -> io.println("\nCompleted: " + done);
    None -> {}
  }

  io.println("\nRemaining tasks:");
  let k: Int = 0;
  while k < tasks.len() {
    match tasks.get(k) {
      Some(t) -> io.println(string.int_to_str(k + 1) + ". " + t);
      None -> {}
    }
    k = k + 1;
  }
  return 0;
}
